actions.action:
def created = []
def unchanged = []
def failed = []

def siet = "pouzivatelia/pu_pouzivatel"
def vsetky = "processIdentifier:\"" + siet + "\""
def stlpce = "meta-title" +
        ",pouzivatelia/pu_pouzivatel-pu_stav_label" +
        ",pouzivatelia/pu_pouzivatel-pu_email" +
        ",pouzivatelia/pu_pouzivatel-pu_priezvisko"

def views = [
        // 1. ZAKLADANIE - typ Task, zuzeny na jednu ulohu. Menu pozna len typy
        //    Case a Task (`FilterType`), samostatny "single task" typ nie je -
        //    ale zakladacia siet ma jediny pripad, takze Task zoznam ma jediny
        //    riadok a chova sa presne tak.
        //    `ElasticTask` nema `processIdentifier`, len `processId` razene per
        //    verziu siete - dopyt preto ide na `transitionId`.
        [id: "pu_novy", name: "Nový používateľ", type: "Task", icon: "person_add",
         query: "transitionId:\"t_pu_novy\"", nets: [], roles: [:], headers: ""],
        // 2. ZOZNAM UCTOV - jeden pripad = jeden ucet.
        //    `nets` tu MUSI byt, inak sa nevykreslia stlpce z datovych poli
        //    (RUNBOOK 4). Vedlajsim ucinkom je tlacidlo "+", ktore vyrobi pripad
        //    bez uctu - ten o sebe povie, ze je nezviazany, a `finish` ho
        //    nepusti. Zakladat sa ma v prvom zobrazeni.
        [id: "pu_vsetci", name: "Používatelia", type: "Case", icon: "group",
         query: vsetky, nets: [siet], roles: [:], headers: stlpce],
]

views.each { v ->
    def id = v.id as String
    try {
        def existing = menu_item(id)
        if (existing != null) {
            // Porovnava sa dopyt A allowedNets - oboje ide do konstruktora
            // a na existujucej polozke sa zmenit neda. Kym sa porovnaval len
            // dopyt, pridanie siete sa ticho zahodilo: podmienka vyhlasila
            // polozku za nezmenenu a stlpce z datovych poli sa nezobrazili.
            def current = getFilterFromMenuItem(existing)
            def currentQuery = ((current?.dataSet?."filter"?.value ?: "") as String)
            def currentNets = ((current?.dataSet?."filter"?.allowedNets ?: []) as List)
                    .collect { it as String } as Set
            def wantNets = (v.nets as List).collect { it as String } as Set
            if (currentQuery == (v.query as String) && currentNets == wantNets) {
                nastav_zobrazenie(existing, v.nets as List, v.headers)
                unchanged << id
                return
            }
            // PORADIE JE POVINNE: najprv polozka, potom filter. Naopak to padne
            // na `IllegalArgumentException: Could not find Case with id [...]`,
            // lebo `deleteMenuItem` si filter este raz nacita podla id na polozke.
            deleteMenuItem(existing)
            if (current != null) {
                deleteFilter(current)
            }
        }
        def item = createOrUpdateMenuItem(
                id,                 // menu_item_identifier
                "pouzivatelia",     // URI cesta - MUSI sedet s uriNodes v processes.json
                v.type as String,
                v.query as String,
                v.icon as String,
                v.name as String,
                v.nets as List,     // allowedNets - bez toho "+" nefunguje
                v.roles as Map,
                [:]                 // bannedRoles - dourcuje aritu na projektovu
        )
        if (item) { created << id } else { failed << id }
        nastav_zobrazenie(item, v.nets as List, v.headers)
    } catch (Exception e) {
        failed << (id + " (" + e.getClass().simpleName + ": " + e.message + ")")
    }
}

def summary = "Menu Používateľov – " + (created.size() + unchanged.size()) + "/" + views.size()
if (failed) {
    summary = "CHYBA menu Používateľov – nepodarilo sa: " + failed.join(", ")
}
changeCaseProperty("title").about { summary }

document.function:
{ def menuItem, def nets, def headers ->
    // enable_case_title  - vypnutý dialóg "Vyplňte názov prípadu" pri "+".
    // default_headers    - predvolené stĺpce zoznamu.
    // Ani jedno nie je argument `createOrUpdateMenuItem`.
    if (menuItem == null) return
    def payload = [:]
    if (nets) {
        payload.put("enable_case_title", ["value": false, "type": "boolean"])
        payload.put("case_require_title_in_creation", ["value": false, "type": "boolean"])
    }
    if (headers) {
        payload.put("default_headers", ["value": headers as String, "type": "text"])
    }
    if (payload) {
        setData("view", menuItem, payload)
    }
}

{ def identifier ->
    // `findMenuItem(id)` z ActionDelegate existujucu polozku nenajde (hlada
    // v inom rozsahu), takze by sa pri kazdom spusteni zalozila druha sada.
    def id = ((identifier ?: "") as String).trim()
    if (!id) return null
    def items = findCases { it.processIdentifier.eq("preference_filter_item") }
    return items?.find { ((it.dataSet["menu_item_identifier"]?.value ?: "") as String) == id }
}
